(2229995, 306942, 29293, '<td valign="top">nice persepctive</td>', 'nice persepctive', '2006-03-15 10:13:07.000000', NULL, 1),
(2229998, 304830, 7322, '<td valign="top">Based on the title and the fact that there is a dock (although I wouldn''t have noticed it from this overexposed view without coaching from the title) I will assume some thought went into the composition. Still, it isn''t a particulalry well-thought out composition,IMO. This placement of the shoes in conjuction with the background doesn''t create a dynamic composition, in my view, and the shoes just aren''t enough of a focal point to capture my interest. There are issues with the size of this image, as well. It is difficult to evaluate the image quality from this size. You''ll here it more than once, but it is really worthwhile to use the optimum image size of 640.</td>', 'Based on the title and the fact that there is a dock (although I wouldn''t have noticed it from this overexposed view without coaching from the title) I will assume some thought went into the composition. Still, it isn''t a particulalry well-thought out composition,IMO. This placement of the shoes in conjuction with the background doesn''t create a dynamic composition, in my view, and the shoes just aren''t enough of a focal point to capture my interest. There are issues with the size of this image, as well. It is difficult to evaluate the image quality from this size. You''ll here it more than once, but it is really worthwhile to use the optimum image size of 640.', '2006-03-15 10:13:52.000000', NULL, 1),
(2230000, 306224, 29293, '<td valign="top">nice perspective</td>', 'nice perspective', '2006-03-15 10:14:31.000000', NULL, 1),
