INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2230007, 306691, 29293, '<td valign="top">very nice and the background works</td>', 'very nice and the background works', '2006-03-15 10:16:28.000000', NULL, 1),
(2230008, 305151, 35804, '<td valign="top">Nice tones and textures...very nice.</td>', 'Nice tones and textures...very nice.', '2006-03-15 10:16:29.000000', NULL, 1),
(2230009, 306906, 54665, '<td valign="top">Would have liked a little more blade to get the point better. Nice shot though, good angle.</td>', 'Would have liked a little more blade to get the point better. Nice shot though, good angle.', '2006-03-15 10:16:39.000000', NULL, 1),
(2230010, 305151, 7322, '<td valign="top">I like the overall quality of this shot. I''m not sure if centering the subject was the best choice, although I like the angle of the boot. I''m wondering if it wouldn''t be more dynamic if the boot were placed in one of the lower corners of the frame?</td>', 'I like the overall quality of this shot. I''m not sure if centering the subject was the best choice, although I like the angle of the boot. I''m wondering if it wouldn''t be more dynamic if the boot were placed in one of the lower corners of the frame?', '2006-03-15 10:16:52.000000', NULL, 1),
(2230011, 306856, 29293, '<td valign="top">i wish there was better light on his face</td>', 'i wish there was better light on his face', '2006-03-15 10:16:54.000000', NULL, 1),
(2230013, 306318, 29293, '<td valign="top">cute idea i wish her face was in focus too</td>', 'cute idea i wish her face was in focus too', '2006-03-15 10:17:22.000000', NULL, 1),
(2230014, 306418, 54665, '<td valign="top">Makes me want to fly. Nice shot!</td>', 'Makes me want to fly. Nice shot!', '2006-03-15 10:17:37.000000', NULL, 1),
(2230015, 306937, 35804, '<td valign="top">Oh!..and now for something completely different...excellent idea...well done.</td>', 'Oh!..and now for something completely different...excellent idea...well done.', '2006-03-15 10:18:10.000000', NULL, 1),
(2230017, 306394, 7322, '<td valign="top">A bit too shiny with several hot-spots from what looks like direct flash. The colors (I''m seeing puce and chartreuse on my monitor) are really horrible together, making this an overall unpleasant viewing experience. Sorry, this just looks awful to me.</td>', 'A bit too shiny with several hot-spots from what looks like direct flash. The colors (I''m seeing puce and chartreuse on my monitor) are really horrible together, making this an overall unpleasant viewing experience. Sorry, this just looks awful to me.', '2006-03-15 10:18:57.000000', NULL, 1),
(2230018, 305172, 35804, '<td valign="top">Nice work...reminds me of a catalog shot.</td>', 'Nice work...reminds me of a catalog shot.', '2006-03-15 10:19:29.000000', NULL, 1),
(2230019, 306103, 42196, '<td valign="top">AT boots?</td>', 'AT boots?', '2006-03-15 10:19:35.000000', NULL, 1),
(2230022, 306606, 29293, '<td valign="top">very nice use of perspective!</td>', 'very nice use of perspective!', '2006-03-15 10:21:49.000000', NULL, 1),
(2230025, 306203, 15266, '<td valign="top">The boots are great and I like the way you arranged them heel to toe, however, all of the other textures, patterns, and colors in the shot really distract from the good parts.</td>', 'The boots are great and I like the way you arranged them heel to toe, however, all of the other textures, patterns, and colors in the shot really distract from the good parts.', '2006-03-15 10:22:02.000000', NULL, 1),
(2230026, 306032, 7322, '<td valign="top">I like the overall composition. I only see one foot which looks odd and somewhat unnatural. I''d like to see both of the feet in a more natural pose. There is a drab quality, overall that makes me wonder if this would be better in b&amp;w.</td>', 'I like the overall composition. I only see one foot which looks odd and somewhat unnatural. I''d like to see both of the feet in a more natural pose. There is a drab quality, overall that makes me wonder if this would be better in b&w.', '2006-03-15 10:22:09.000000', NULL, 1),
(2230027, 306482, 29293, '<td valign="top">different and nice</td>', 'different and nice', '2006-03-15 10:22:50.000000', NULL, 1),
(2230029, 304725, 29293, '<td valign="top">nice color</td>', 'nice color', '2006-03-15 10:23:10.000000', NULL, 1),
(2230031, 306263, 7322, '<td valign="top">The direct flash gives this a harsh appearance. The subject, a young girl, wearing pink, against a pink background, calls for much softer lighting.</td>', 'The direct flash gives this a harsh appearance. The subject, a young girl, wearing pink, against a pink background, calls for much softer lighting.', '2006-03-15 10:23:27.000000', NULL, 1),
(2230032, 306469, 29293, '<td valign="top">nice color!</td>', 'nice color!', '2006-03-15 10:23:37.000000', NULL, 1),
(2230035, 306265, 7322, '<td valign="top">A bit out of focus. I think with a composition like this, you could have included the whole figure and still made the shoes a major focal point. This just looks chopped off.</td>', 'A bit out of focus. I think with a composition like this, you could have included the whole figure and still made the shoes a major focal point. This just looks chopped off.', '2006-03-15 10:24:57.000000', NULL, 1),
(2230036, 306710, 29293, '<td valign="top">nice perspective</td>', 'nice perspective', '2006-03-15 10:25:03.000000', NULL, 1),
(2230039, 306418, 29293, '<td valign="top">this is different and i like the action</td>', 'this is different and i like the action', '2006-03-15 10:25:55.000000', NULL, 1),
(2230043, 306209, 29293, '<td valign="top">i like the tilt</td>', 'i like the tilt', '2006-03-15 10:26:55.000000', NULL, 1),
(2230044, 306691, 46885, '<td valign="top">That would be a good picture, but you need some sharpness there...</td>', 'That would be a good picture, but you need some sharpness there...', '2006-03-15 10:27:10.000000', NULL, 1),
(2230047, 306690, 15266, '<td valign="top">One shoe just looks odd to me.  I wish you''d used both. Nice lighting and interesting angle.</td>', 'One shoe just looks odd to me.  I wish you''d used both. Nice lighting and interesting angle.', '2006-03-15 10:27:35.000000', NULL, 1),
(2230048, 306856, 46885, '<td valign="top">shoe is nowhere near the focus of this photo. Nice smile, thou..</td>', 'shoe is nowhere near the focus of this photo. Nice smile, thou..', '2006-03-15 10:27:49.000000', NULL, 1),
(2230057, 305102, 9643, '<td valign="top">I like the composition in this shot</td>', 'I like the composition in this shot', '2006-03-15 10:29:12.000000', NULL, 1),
(2230067, 305290, 46885, '<td valign="top">Bit dull on background, isn''t it?</td>', 'Bit dull on background, isn''t it?', '2006-03-15 10:31:19.000000', NULL, 1),
(2230072, 306394, 46885, '<td valign="top">You haven''t even walked in those! Foot makeup it is and footwear it ain''t</td>', 'You haven''t even walked in those! Foot makeup it is and footwear it ain''t', '2006-03-15 10:32:27.000000', NULL, 1),
(2230077, 306511, 9643, '<td valign="top">Very creative</td>', 'Very creative', '2006-03-15 10:33:31.000000', NULL, 1),
(2230078, 304562, 15266, '<td valign="top">Wow - not sure what you did for processing, but its harsh.  Also, I see a shoe, a drink, some roses, some ribbons, a surface with texture.... there is a LOT going on.  I think your composition would work better with fewer supporting items.</td>', 'Wow - not sure what you did for processing, but its harsh.  Also, I see a shoe, a drink, some roses, some ribbons, a surface with texture.... there is a LOT going on.  I think your composition would work better with fewer supporting items.', '2006-03-15 10:33:34.000000', NULL, 1),
(2230079, 305439, 7322, '<td valign="top">This is one of those set-ups that has only one function--meeting the challenge. While this is a photo of shoes, and there is some creativity behind the idea, ultimately, it is the type of shot that has no place outside the very narrow confines of this one challenge. This type of photograph doesn''t seem to consider asthetic values at all. Why would someone actually want to view this photograph? I''m not asking this to be sarcastic. This is something every member should ask themselves before submitting to any challenge.</td>', 'This is one of those set-ups that has only one function--meeting the challenge. While this is a photo of shoes, and there is some creativity behind the idea, ultimately, it is the type of shot that has no place outside the very narrow confines of this one challenge. This type of photograph doesn''t seem to consider asthetic values at all. Why would someone actually want to view this photograph? I''m not asking this to be sarcastic. This is something every member should ask themselves before submitting to any challenge.', '2006-03-15 10:33:43.000000', NULL, 1),
(2230089, 305540, 15266, '<td valign="top">Love that you caught the moon in the shot.  Nicely done.</td>', 'Love that you caught the moon in the shot.  Nicely done.', '2006-03-15 10:35:31.000000', NULL, 1),
(2230090, 304569, 9643, '<td valign="top">This took a minute to grow on me but it did and now I like the grainy effect that the tint gives to it.</td>', 'This took a minute to grow on me but it did and now I like the grainy effect that the tint gives to it.', '2006-03-15 10:36:11.000000', NULL, 1),
(2230093, 306769, 46885, '<td valign="top">Sharpness!</td>', 'Sharpness!', '2006-03-15 10:37:46.000000', NULL, 1),
(2230098, 306221, 39578, '<td valign="top">Would have scored it higher if subject was posed like the statue.</td>', 'Would have scored it higher if subject was posed like the statue.', '2006-03-15 10:38:52.000000', NULL, 1),
(2230100, 306906, 46885, '<td valign="top">What is it? Looks almost abstract and as such is totally out of place in the theme... shallow dof is a distraction here, too.</td>', 'What is it? Looks almost abstract and as such is totally out of place in the theme... shallow dof is a distraction here, too.', '2006-03-15 10:39:26.000000', NULL, 1),
