(2232412, 305172, 31533, '<td valign="top">good idea but it looks a bit oversharpened to me.</td>', 'good idea but it looks a bit oversharpened to me.', '2006-03-16 01:31:41.000000', NULL, 1),
(2232442, 306318, 54490, '<td valign="top">I love that she has the look on her face like a child who pauses to step on a bug without a lot of thought before moving on. The missing hands seem natural to me, perhaps from all those years of pulling mine into my sleeves during the cold walk to school.</td>', 'I love that she has the look on her face like a child who pauses to step on a bug without a lot of thought before moving on. The missing hands seem natural to me, perhaps from all those years of pulling mine into my sleeves during the cold walk to school.', '2006-03-16 01:52:33.000000', NULL, 1),
(2232459, 304566, 54490, '<td valign="top">Wow. That''s quite a shoe. It took me a minute to figure out that the straps are clear. Part of me is dying to know where in the world you''d wear a shoe like this. The rest of me is certain some things are better left unsaid. :)</td>', 'Wow. That''s quite a shoe. It took me a minute to figure out that the straps are clear. Part of me is dying to know where in the world you''d wear a shoe like this. The rest of me is certain some things are better left unsaid. :)', '2006-03-16 01:57:03.000000', NULL, 1),
