(2233367, 306351, 44490, '<td valign="top">Nice composition, striking profile - image seems too soft, sharper (detail to show sharpness) would be better.</td>', 'Nice composition, striking profile - image seems too soft, sharper (detail to show sharpness) would be better.', '2006-03-16 11:56:34.000000', NULL, 1),
(2233368, 306774, 40667, '<td valign="top">Nice, really like it! B&amp;W was a great tonal choice here! positioning nice, like your prespective! everylittle thing here really makes the pic as a whole! blowing hair, rock, white cap, Very Nice!</td>', 'Nice, really like it! B&W was a great tonal choice here! positioning nice, like your prespective! everylittle thing here really makes the pic as a whole! blowing hair, rock, white cap, Very Nice!', '2006-03-16 11:56:37.000000', NULL, 1),
(2233371, 306434, 44490, '<td valign="top">Nice composition, subject, heel, and capture of action.  I usually don''t like odd angles, but I can see why you used it in this case.</td>', 'Nice composition, subject, heel, and capture of action.  I usually don''t like odd angles, but I can see why you used it in this case.', '2006-03-16 11:57:14.000000', NULL, 1),
