INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2234523, 306559, 26757, '<td valign="top">Interesting composition, and interpretation of the subject.</td>', 'Interesting composition, and interpretation of the subject.', '2006-03-16 20:39:09.000000', NULL, 1),
(2234531, 306351, 26757, '<td valign="top">Almost too dark... Too much of the shoe falls into shadow.</td>', 'Almost too dark... Too much of the shoe falls into shadow.', '2006-03-16 20:41:47.000000', NULL, 1),
(2234539, 306286, 26757, '<td valign="top">Really like what you did here. Like the motion, that fact that the shoes are not an "in-your-face-so obvious" point of subject. Really like your coloration, the shadow quality and the pure tonal range of the highlights, as well.<br/>Nicely done.</td>', 'Really like what you did here. Like the motion, that fact that the shoes are not an "in-your-face-so obvious" point of subject. Really like your coloration, the shadow quality and the pure tonal range of the highlights, as well.Nicely done.', '2006-03-16 20:45:02.000000', NULL, 1),
(2234545, 306856, 26757, '<td valign="top">The subject falls too far into the shadow of the tonal range, as does too much of the central range of the image. Nice concept, though.</td>', 'The subject falls too far into the shadow of the tonal range, as does too much of the central range of the image. Nice concept, though.', '2006-03-16 20:46:23.000000', NULL, 1),
(2234548, 306832, 26757, '<td valign="top">Sooo true...</td>', 'Sooo true...', '2006-03-16 20:47:36.000000', NULL, 1),
(2234556, 305146, 26757, '<td valign="top">Interesting, would be stronger, to me, without the colored toe nails... Maybe, black &amp; white.</td>', 'Interesting, would be stronger, to me, without the colored toe nails... Maybe, black & white.', '2006-03-16 20:49:32.000000', NULL, 1),
(2234563, 305541, 26757, '<td valign="top">Does make you wonder, doesn''t it? I mean why do people toss the shoes onto the line? Why are shoes so often along the side of the road? Are they run-aways?</td>', 'Does make you wonder, doesn''t it? I mean why do people toss the shoes onto the line? Why are shoes so often along the side of the road? Are they run-aways?', '2006-03-16 20:51:40.000000', NULL, 1),
(2234567, 305050, 50935, '<td valign="top">Nice Shot. I don''t like the frame however.</td>', 'Nice Shot. I don''t like the frame however.', '2006-03-16 20:52:03.000000', NULL, 1),
(2234569, 305074, 26757, '<td valign="top">Very cute perspective.</td>', 'Very cute perspective.', '2006-03-16 20:52:34.000000', NULL, 1),
(2234571, 306896, 26757, '<td valign="top">Focus on the near, small toe is too soft, as is the focus on the tattoo... The out of focus of these near areas throws off the image.</td>', 'Focus on the near, small toe is too soft, as is the focus on the tattoo... The out of focus of these near areas throws off the image.', '2006-03-16 20:52:58.000000', NULL, 1),
(2234578, 306952, 26757, '<td valign="top">Great idea, but the cat falls far deeply into the tonal range of the shadow... The viewer wishes and needs to see more detail than is available in this image.</td>', 'Great idea, but the cat falls far deeply into the tonal range of the shadow... The viewer wishes and needs to see more detail than is available in this image.', '2006-03-16 20:54:44.000000', NULL, 1),
(2234579, 305644, 26757, '<td valign="top">Think that this image could have been made better by changing your position... Might have been stronger, had you shot it from a lower angle.</td>', 'Think that this image could have been made better by changing your position... Might have been stronger, had you shot it from a lower angle.', '2006-03-16 20:54:54.000000', NULL, 1),
(2234581, 305018, 50935, '<td valign="top">nice patagonia shot</td>', 'nice patagonia shot', '2006-03-16 20:55:40.000000', NULL, 1),
