(2234583, 305544, 26757, '<td valign="top">Interesting vantage point, would have liked to see more players feet in the far background, though.</td>', 'Interesting vantage point, would have liked to see more players feet in the far background, though.', '2006-03-16 20:55:57.000000', NULL, 1),
(2234585, 305327, 50935, '<td valign="top">a used pair would have been great.</td>', 'a used pair would have been great.', '2006-03-16 20:56:08.000000', NULL, 1),
