(2234607, 305631, 26757, '<td valign="top">Very nice. Works well in B&amp;W, and good cropping.</td>', 'Very nice. Works well in B&W, and good cropping.', '2006-03-16 21:02:40.000000', NULL, 1),
(2234610, 306691, 26757, '<td valign="top">Very nice handling of the subject, good use of framing. I like the depth of focus, as well. The fact that she is walking out of the image... Nicely done.</td>', 'Very nice handling of the subject, good use of framing. I like the depth of focus, as well. The fact that she is walking out of the image... Nicely done.', '2006-03-16 21:05:16.000000', NULL, 1),
(2234613, 306609, 26757, '<td valign="top">Good use of lighting and depth of field.</td>', 'Good use of lighting and depth of field.', '2006-03-16 21:06:16.000000', NULL, 1),
