(2234624, 306774, 26757, '<td valign="top">Very nice use of B&amp;W, depth of field and focus, nice tonal range, use of shadow and highlight... That you still have detail in the shadow. Nice interpretation. Kudos.</td>', 'Very nice use of B&W, depth of field and focus, nice tonal range, use of shadow and highlight... That you still have detail in the shadow. Nice interpretation. Kudos.', '2006-03-16 21:10:42.000000', NULL, 1),
(2234628, 305918, 26757, '<td valign="top">Excellent use of B&amp;W Tonal range, details in the shadow, texture in the highlights. Interesting subject interpretation.</td>', 'Excellent use of B&W Tonal range, details in the shadow, texture in the highlights. Interesting subject interpretation.', '2006-03-16 21:11:41.000000', NULL, 1),
(2234632, 305018, 26757, '<td valign="top">Good depth of focus. Nice colors.</td>', 'Good depth of focus. Nice colors.', '2006-03-16 21:12:42.000000', NULL, 1),
