(2238595, 305485, 54697, '<td valign="top">Love this image, great effort</td>', 'Love this image, great effort', '2006-03-19 04:12:34.000000', NULL, 1),
(2238605, 304728, 17507, '<td valign="top">technically strong, but not so strong conceptually and compositionally. the shoes are presented without reason, giving the viewer no emotional connection to the image, and the composition does not present a fresh or unusual perspective on an ordinary object.</td>', 'technically strong, but not so strong conceptually and compositionally. the shoes are presented without reason, giving the viewer no emotional connection to the image, and the composition does not present a fresh or unusual perspective on an ordinary object.', '2006-03-19 04:40:08.000000', NULL, 1),
(2238606, 306399, 17507, '<td valign="top">as an abstraction, effective; the object is basically unrecognizable. the white space on the left seems to serve no purpose; it is simply empty. I don''t think there are enough strong shapes in the composition to support so much empty space.</td>', 'as an abstraction, effective; the object is basically unrecognizable. the white space on the left seems to serve no purpose; it is simply empty. I don''t think there are enough strong shapes in the composition to support so much empty space.', '2006-03-19 04:41:00.000000', NULL, 1),
(2238607, 306500, 17507, '<td valign="top">nice action shot. definitely an unusual perspective!</td>', 'nice action shot. definitely an unusual perspective!', '2006-03-19 04:41:25.000000', NULL, 1),
(2238611, 306931, 17507, '<td valign="top">interesting double exposure. I''m not sure I see why you left the big toe raised... I look forward to reading your comments afterward.</td>', 'interesting double exposure. I''m not sure I see why you left the big toe raised... I look forward to reading your comments afterward.', '2006-03-19 04:42:36.000000', NULL, 1),
(2238612, 306769, 17507, '<td valign="top">wow, what a perfect subject for this challenge. I just wish the light weren''t so harsh and flat and that the focus were sharper.</td>', 'wow, what a perfect subject for this challenge. I just wish the light weren''t so harsh and flat and that the focus were sharper.', '2006-03-19 04:43:17.000000', NULL, 1),
(2238614, 306776, 17507, '<td valign="top">I recognize the clip-on cycling shoe, but the others are outside of my knowledge...</td>', 'I recognize the clip-on cycling shoe, but the others are outside of my knowledge...', '2006-03-19 04:45:03.000000', NULL, 1),
(2238616, 306619, 17507, '<td valign="top">To me, the clockwise rotation is disorienting and nothing more. If this were rotated 90 degrees counter-clockwise, I think this would be a lot stronger.</td>', 'To me, the clockwise rotation is disorienting and nothing more. If this were rotated 90 degrees counter-clockwise, I think this would be a lot stronger.', '2006-03-19 04:46:48.000000', NULL, 1),
(2238620, 306128, 17507, '<td valign="top">The image quality is terrible! It also looks like it''s been stretched vertically.</td>', 'The image quality is terrible! It also looks like it''s been stretched vertically.', '2006-03-19 04:48:02.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2238621, 304435, 17507, '<td valign="top">apparently the title is a reference to potentiality and not actuality.</td>', 'apparently the title is a reference to potentiality and not actuality.', '2006-03-19 04:48:33.000000', NULL, 1),
(2238623, 304725, 17507, '<td valign="top">ah, one of precious few that have some sort of theme to them rather than just being a pair of shoes. thanks for putting thought into your entry.</td>', 'ah, one of precious few that have some sort of theme to them rather than just being a pair of shoes. thanks for putting thought into your entry.', '2006-03-19 04:49:28.000000', NULL, 1),
(2238625, 306874, 17507, '<td valign="top">hmm, do nikes taste better? maybe the higher rubber content helps keep the gators regular.</td>', 'hmm, do nikes taste better? maybe the higher rubber content helps keep the gators regular.', '2006-03-19 04:50:08.000000', NULL, 1),
(2238628, 306286, 17507, '<td valign="top">Shoes don''t strike me as being the focal point of this image - they''re merely incidental to this scene.</td>', 'Shoes don''t strike me as being the focal point of this image - they''re merely incidental to this scene.', '2006-03-19 04:52:06.000000', NULL, 1),
(2238631, 306863, 17507, '<td valign="top">gotta fix that focus. it just doesn''t work when the foreground is fuzzy and the background is sharp.</td>', 'gotta fix that focus. it just doesn''t work when the foreground is fuzzy and the background is sharp.', '2006-03-19 04:54:06.000000', NULL, 1),
(2238634, 305060, 17507, '<td valign="top">great image. check your spelling on that title :)</td>', 'great image. check your spelling on that title :)', '2006-03-19 04:54:37.000000', NULL, 1),
(2238635, 306886, 17507, '<td valign="top">The gas mask is, at this point, painfully cliche.</td>', 'The gas mask is, at this point, painfully cliche.', '2006-03-19 04:55:11.000000', NULL, 1),
(2238636, 306283, 17507, '<td valign="top">gorgeous processing... this one really works.</td>', 'gorgeous processing... this one really works.', '2006-03-19 04:55:42.000000', NULL, 1),
(2238637, 304599, 17507, '<td valign="top">.</td>', '.', '2006-03-19 04:55:57.000000', NULL, 1),
(2238638, 305143, 17507, '<td valign="top">Musty blusterbuckets. What a fiend~!</td>', 'Musty blusterbuckets. What a fiend~!', '2006-03-19 04:58:14.000000', NULL, 1),
(2238639, 305050, 17507, '<td valign="top">great image. the deep colors are delicious to look at and the high-contrast processing is perfect for the wrinkle of leather and the weave of denim.</td>', 'great image. the deep colors are delicious to look at and the high-contrast processing is perfect for the wrinkle of leather and the weave of denim.', '2006-03-19 04:59:41.000000', NULL, 1),
(2238641, 305485, 17507, '<td valign="top">Ladies and gentlemen, we have our winner.</td>', 'Ladies and gentlemen, we have our winner.', '2006-03-19 05:01:45.000000', NULL, 1),
(2238643, 306867, 17507, '<td valign="top">sassy! I like this one.</td>', 'sassy! I like this one.', '2006-03-19 05:02:26.000000', NULL, 1),
(2238645, 306102, 17507, '<td valign="top">what a stark image. the expression on the model''s face is intriguing. she looks like she''s made out of chalk - and the nearly equal tonality of shoes, eyes, hair, and shadow make this very surreal. those shoes are fantastically ugly.</td>', 'what a stark image. the expression on the model''s face is intriguing. she looks like she''s made out of chalk - and the nearly equal tonality of shoes, eyes, hair, and shadow make this very surreal. those shoes are fantastically ugly.', '2006-03-19 05:04:06.000000', NULL, 1),
(2238648, 306394, 17507, '<td valign="top">eek. too wet and slimy looking - simply unattractive.</td>', 'eek. too wet and slimy looking - simply unattractive.', '2006-03-19 05:05:03.000000', NULL, 1),
(2238713, 305862, 48115, '<td valign="top">a boobshot.. this must winn...</td>', 'a boobshot.. this must winn...', '2006-03-19 07:58:39.000000', NULL, 1),
(2238715, 306222, 53964, '<td valign="top">The background is very distracting. My eye goes constantly to the...patio?<br/>Puppy''s shoes seem to be the last thing they get to, after covering everything else.</td>', 'The background is very distracting. My eye goes constantly to the...patio?Puppy''s shoes seem to be the last thing they get to, after covering everything else.', '2006-03-19 08:09:23.000000', NULL, 1),
(2238825, 306874, 49031, '<td valign="top">what imagination!</td>', 'what imagination!', '2006-03-19 10:49:07.000000', NULL, 1),
(2238841, 306418, 11854, '<td valign="top">Great shot! One of the three 10''s I gave.</td>', 'Great shot! One of the three 10''s I gave.', '2006-03-19 11:13:46.000000', NULL, 1),
(2238843, 306798, 11854, '<td valign="top">Great shot! One of the three 10''s I gave.</td>', 'Great shot! One of the three 10''s I gave.', '2006-03-19 11:14:21.000000', NULL, 1),
(2238844, 306874, 11854, '<td valign="top">This gave me a LOL moment. Thanks!</td>', 'This gave me a LOL moment. Thanks!', '2006-03-19 11:15:23.000000', NULL, 1),
(2238845, 305565, 11854, '<td valign="top">Very original! Nice shot!</td>', 'Very original! Nice shot!', '2006-03-19 11:15:46.000000', NULL, 1),
(2238849, 305485, 11854, '<td valign="top">Ouch! Are they real tattoo''s? Very nice shot, original.</td>', 'Ouch! Are they real tattoo''s? Very nice shot, original.', '2006-03-19 11:18:03.000000', NULL, 1),
(2238891, 305683, 43774, '<td valign="top">What a great idea!!! Exposure could use some work but I love the concept.<br/>Back for another comment.....that looks a lot like the Heart''s Content lighthouse, is it?.....bumping you up to a 10 because I just love this picture</td>', 'What a great idea!!! Exposure could use some work but I love the concept.Back for another comment.....that looks a lot like the Heart''s Content lighthouse, is it?.....bumping you up to a 10 because I just love this picture', '2006-03-19 11:43:30.000000', NULL, 1),
(2238967, 305541, 51614, '<td valign="top">Creative!<br/> <br/>I wish you could see the shoe laces actually tied to the wire.</td>', 'Creative! I wish you could see the shoe laces actually tied to the wire.', '2006-03-19 12:39:23.000000', NULL, 1),
(2238969, 306440, 51614, '<td valign="top">Love the cowboy boots and green converse!<br/>And the lovely background!<br/>I just wish the picture was a bit more sharpened.</td>', 'Love the cowboy boots and green converse!And the lovely background!I just wish the picture was a bit more sharpened.', '2006-03-19 12:41:08.000000', NULL, 1),
(2238971, 305862, 51614, '<td valign="top">Very cute!<br/>But I wish her fingernails were the same color as her toes and didn''t blend into the white ground.</td>', 'Very cute!But I wish her fingernails were the same color as her toes and didn''t blend into the white ground.', '2006-03-19 12:43:53.000000', NULL, 1),
(2239281, 306811, 48761, '<td valign="top">Good choice for sepia.</td>', 'Good choice for sepia.', '2006-03-19 15:34:07.000000', NULL, 1),
(2239282, 306318, 48761, '<td valign="top">Cute idea.  Well executed.</td>', 'Cute idea.  Well executed.', '2006-03-19 15:35:13.000000', NULL, 1),
(2239284, 304599, 48761, '<td valign="top">What''s with the hairy legs and pink undies?!  I''m scared!</td>', 'What''s with the hairy legs and pink undies?!  I''m scared!', '2006-03-19 15:35:58.000000', NULL, 1),
(2239287, 306798, 48761, '<td valign="top">Very effective.  My highest vote so far.  I hope you gave the firefighter something else to wear while he was putting out the house.</td>', 'Very effective.  My highest vote so far.  I hope you gave the firefighter something else to wear while he was putting out the house.', '2006-03-19 15:37:07.000000', NULL, 1),
(2239289, 305690, 48761, '<td valign="top">Try diffusing the flash some to get rid of the shadows.  Bitchin'' green shoes though!</td>', 'Try diffusing the flash some to get rid of the shadows.  Bitchin'' green shoes though!', '2006-03-19 15:38:32.000000', NULL, 1),
(2239292, 306509, 48761, '<td valign="top">Great framing.</td>', 'Great framing.', '2006-03-19 15:40:14.000000', NULL, 1),
(2239294, 306845, 48761, '<td valign="top">Great lighting.  Personally, I find the rocks in the background distracting, especially at this angle where we see so much of them.</td>', 'Great lighting.  Personally, I find the rocks in the background distracting, especially at this angle where we see so much of them.', '2006-03-19 15:42:22.000000', NULL, 1),
(2239295, 306793, 48761, '<td valign="top">Great "moment", and for that I will forgive the fuzzy focus.  One of my favorite images thus far.  Should be a top 20, but probably won''t be.  I give ''er an 8.</td>', 'Great "moment", and for that I will forgive the fuzzy focus.  One of my favorite images thus far.  Should be a top 20, but probably won''t be.  I give ''er an 8.', '2006-03-19 15:43:33.000000', NULL, 1),
(2239296, 306866, 48761, '<td valign="top">Good lighting, good idea, good execution.</td>', 'Good lighting, good idea, good execution.', '2006-03-19 15:43:54.000000', NULL, 1),
(2239298, 306931, 48761, '<td valign="top">Probably would have rated higher with me if the foot were inside the lines of the shoe.  I understand that would be difficult to do.  :-)  Good image though!</td>', 'Probably would have rated higher with me if the foot were inside the lines of the shoe.  I understand that would be difficult to do.  :-)  Good image though!', '2006-03-19 15:44:39.000000', NULL, 1),
(2239300, 306283, 48761, '<td valign="top">Cute model!  Great use of all the patterns in the background.  I might like it better rotated 90 CCW, or shot at an angle.</td>', 'Cute model!  Great use of all the patterns in the background.  I might like it better rotated 90 CCW, or shot at an angle.', '2006-03-19 15:46:02.000000', NULL, 1),
(2239303, 304769, 48761, '<td valign="top">Great lighting.  The suitcase matches the boots -- so much better than looking at 200 pictures of shoes on a sidewalk, carpet, beach, etcetera.</td>', 'Great lighting.  The suitcase matches the boots -- so much better than looking at 200 pictures of shoes on a sidewalk, carpet, beach, etcetera.', '2006-03-19 15:46:43.000000', NULL, 1),
(2239304, 305000, 48761, '<td valign="top">Great colors, great idea and execution.</td>', 'Great colors, great idea and execution.', '2006-03-19 15:47:31.000000', NULL, 1),
(2239305, 306908, 48761, '<td valign="top">Hot.  Love the B&amp;W.  Good contrast.  Not so crazy about the fake bricks, but I understand how building a brick wall just for the challenge would be a bit out of reach.</td>', 'Hot.  Love the B&W.  Good contrast.  Not so crazy about the fake bricks, but I understand how building a brick wall just for the challenge would be a bit out of reach.', '2006-03-19 15:48:42.000000', NULL, 1),
(2239306, 306790, 48761, '<td valign="top">Hmm... cute picture.  I don''t quite see the "footwear" connection.</td>', 'Hmm... cute picture.  I don''t quite see the "footwear" connection.', '2006-03-19 15:49:20.000000', NULL, 1),
(2239308, 306677, 48761, '<td valign="top">The B&amp;W sure makes grungy old shoes look more like art than the color photos do!  Like the lighting and the background on this one.  Good DOF.</td>', 'The B&W sure makes grungy old shoes look more like art than the color photos do!  Like the lighting and the background on this one.  Good DOF.', '2006-03-19 15:50:11.000000', NULL, 1),
(2239309, 306727, 48761, '<td valign="top">Great pic, I''d like it better if I could make out the bottom of the shoe better.  Thanks for not taking a picture of some sneakers on your porch.</td>', 'Great pic, I''d like it better if I could make out the bottom of the shoe better.  Thanks for not taking a picture of some sneakers on your porch.', '2006-03-19 15:51:22.000000', NULL, 1),
(2239312, 305071, 48761, '<td valign="top">I like the lighting and the location!</td>', 'I like the lighting and the location!', '2006-03-19 15:52:14.000000', NULL, 1),
(2239320, 305439, 48761, '<td valign="top">LOL''d at the idea, I don''t think I''d put it together without the title.  Try using lighting outside the onboard flash.  Also, how about seeing the kitchen in the background.  Looks like you''re using a point and shoot (without much control on aperature), try stepping back a few paces and zooming in -- it''ll give you that depth of field you long for!  Gave you a six.  Good effort!</td>', 'LOL''d at the idea, I don''t think I''d put it together without the title.  Try using lighting outside the onboard flash.  Also, how about seeing the kitchen in the background.  Looks like you''re using a point and shoot (without much control on aperature), try stepping back a few paces and zooming in -- it''ll give you that depth of field you long for!  Gave you a six.  Good effort!', '2006-03-19 15:56:02.000000', NULL, 1),
(2239335, 304728, 19670, '<td valign="top">Pretty good--could be a product/catalog shot.</td>', 'Pretty good--could be a product/catalog shot.', '2006-03-19 16:04:52.000000', NULL, 1),
(2239338, 306165, 19670, '<td valign="top">Like the long exposure.</td>', 'Like the long exposure.', '2006-03-19 16:06:07.000000', NULL, 1),
(2239340, 305540, 19670, '<td valign="top">Suh-weeeet! Great grab, and you included the moon. 9.</td>', 'Suh-weeeet! Great grab, and you included the moon. 9.', '2006-03-19 16:07:15.000000', NULL, 1),
