(2242122, 306944, 47852, '<td valign="top">I like this different take on the challenge theme.  The dof used here was perfect for this shot.</td>', 'I like this different take on the challenge theme.  The dof used here was perfect for this shot.', '2006-03-20 16:06:37.000000', NULL, 1),
(2242127, 306010, 47852, '<td valign="top">Having the ski go across the frame in more of a diagonal might help the composition.  Like the close up though with the appropriate background.</td>', 'Having the ski go across the frame in more of a diagonal might help the composition.  Like the close up though with the appropriate background.', '2006-03-20 16:08:01.000000', NULL, 1),
(2242129, 305540, 47852, '<td valign="top">Like the capture with the moon in the background.  Neat.</td>', 'Like the capture with the moon in the background.  Neat.', '2006-03-20 16:08:08.000000', NULL, 1),
(2242135, 306939, 47852, '<td valign="top">I like that you left the tag left on the new shoe.  The shoes seem tilted slightly in the frame, but not quite enough to make it seem as if it were intentional.  I might have rotated them to straight or else a bit more diagonal.</td>', 'I like that you left the tag left on the new shoe.  The shoes seem tilted slightly in the frame, but not quite enough to make it seem as if it were intentional.  I might have rotated them to straight or else a bit more diagonal.', '2006-03-20 16:09:26.000000', NULL, 1),
